class Solution {
public:
    int largestInteger(int num) {
        int count[10] = {0};
        int digits[10];
        int n = 0;

        int temp = num;
        while (temp > 0) {
            int d = temp % 10;
            count[d]++;
            digits[n++] = d;
            temp /= 10;
        }

        long long result = 0;
        for (int i = n - 1; i >= 0; i--) {
            int d = digits[i];
            int start = (d % 2 == 0) ? 8 : 9;
            for (int j = start; j >= 0; j -= 2) {
                if (count[j] > 0) {
                    count[j]--;
                    result = result * 10 + j;
                    break;
                }
            }
        }

        return (int)result;
    }
};
